/**
 * Autogenerated by Postman CLI (postman mock generate)
 * Manually fixed during dogfooding — now stateful, scoped by an optional
 * x-mock-session header (falls back to "default") so CI runs, the Monitor,
 * and manual/demo use don't stomp on each other's cart state.
 */
const http = require('http');
const PORT = process.env.PORT || 5002;

// Mirrors product-service's catalog closely enough for enrichment — kept
// local so this mock never has to make a real cross-mock HTTP call.
const PRODUCTS = {
  p1: { name: 'Wireless Noise-Cancelling Headphones', price: 149.99 },
  p2: { name: 'Smart Fitness Watch', price: 199.00 },
  p3: { name: 'Ceramic Pour-Over Coffee Set', price: 39.50 },
  p4: { name: 'Memory Foam Throw Pillow', price: 24.99 },
  p5: { name: "Men's Merino Wool Sweater", price: 79.00 },
  p6: { name: "Women's Running Sneakers", price: 89.99 },
  p7: { name: 'The Midnight Orchard (Novel)', price: 14.99 },
  p8: { name: "Learn Cooking: A Beginner's Guide", price: 22.50 },
  p9: { name: 'Stainless Steel Water Bottle', price: 27.00 },
  p10: { name: 'Portable Bluetooth Speaker', price: 59.99 },
};

// sessionKey ("<mockSession>:<userId>") -> [{ productId, quantity }]
const carts = new Map();

function sessionKey(req) {
  const mockSession = req.headers['x-mock-session'] || 'default';
  const userId = req.headers['x-user-id'] || 'demo-user';
  return mockSession + ':' + userId;
}

function getLines(req) {
  const key = sessionKey(req);
  if (!carts.has(key)) carts.set(key, []);
  return carts.get(key);
}

function enrich(lines, userId) {
  const items = lines.map((line) => {
    const product = PRODUCTS[line.productId];
    const price = product ? product.price : 0;
    const name = product ? product.name : 'Unknown product';
    return {
      productId: line.productId,
      name,
      price,
      quantity: line.quantity,
      subtotal: Math.round(price * line.quantity * 100) / 100,
    };
  });
  const total = Math.round(items.reduce((sum, item) => sum + item.subtotal, 0) * 100) / 100;
  return { userId, items, total };
}

function readBody(req, cb) {
  let data = '';
  req.on('data', (chunk) => (data += chunk));
  req.on('end', () => {
    try {
      cb(data ? JSON.parse(data) : {});
    } catch (e) {
      cb({});
    }
  });
}

// Returns the body's unexpected top-level keys (those not in allowedKeys),
// or null if there are none / the body isn't a plain object.
function unexpectedFields(body, allowedKeys) {
  if (typeof body !== 'object' || body === null || Array.isArray(body)) return null;
  const extra = Object.keys(body).filter((key) => !allowedKeys.includes(key));
  return extra.length > 0 ? extra : null;
}

const server = http.createServer((req, res) => {
  const url = new URL(req.url || '', 'http://localhost');
  const pathname = url.pathname;
  const userId = req.headers['x-user-id'] || 'demo-user';

  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'GET,POST,PUT,DELETE,OPTIONS');
  res.setHeader(
    'Access-Control-Allow-Headers',
    'Content-Type,x-user-id,x-mock-response-code,x-mock-scenario,x-api-key,x-mock-session'
  );
  if (req.method === 'OPTIONS') {
    res.writeHead(204);
    return res.end();
  }

  const requestedStatusCode = req.headers['x-mock-response-code'];

  // @endpoint GET /api/cart
  if (req.method === 'GET' && pathname === '/api/cart') {
    const cart = enrich(getLines(req), userId);
    res.writeHead(200, { 'Content-Type': 'application/json' });
    return res.end(JSON.stringify(cart));
  }

  // @endpoint DELETE /api/cart
  if (req.method === 'DELETE' && pathname === '/api/cart') {
    carts.set(sessionKey(req), []);
    const cart = enrich(getLines(req), userId);
    res.writeHead(200, { 'Content-Type': 'application/json' });
    return res.end(JSON.stringify(cart));
  }

  // @endpoint POST /api/cart/items
  if (req.method === 'POST' && pathname === '/api/cart/items') {
    return readBody(req, (body) => {
      const extra = unexpectedFields(body, ['productId', 'quantity']);
      if (extra) {
        res.writeHead(400, { 'Content-Type': 'application/json' });
        return res.end(
          JSON.stringify({ error: `Unexpected field(s) in request body: ${extra.join(', ')}` })
        );
      }
      if (
        requestedStatusCode === '400' ||
        !body.productId ||
        typeof body.quantity !== 'number' ||
        body.quantity < 1
      ) {
        res.writeHead(400, { 'Content-Type': 'application/json' });
        return res.end(
          JSON.stringify({ error: 'productId is required and quantity must be a number >= 1' })
        );
      }
      const lines = getLines(req);
      const existing = lines.find((l) => l.productId === body.productId);
      if (existing) existing.quantity += body.quantity;
      else lines.push({ productId: body.productId, quantity: body.quantity });
      const cart = enrich(lines, userId);
      res.writeHead(200, { 'Content-Type': 'application/json' });
      return res.end(JSON.stringify(cart));
    });
  }

  const itemMatch = pathname.match(/^\/api\/cart\/items\/(.+)$/);

  // @endpoint PUT /api/cart/items/{productId}
  if (req.method === 'PUT' && itemMatch) {
    return readBody(req, (body) => {
      const productId = decodeURIComponent(itemMatch[1]);
      const extra = unexpectedFields(body, ['quantity']);
      if (extra) {
        res.writeHead(400, { 'Content-Type': 'application/json' });
        return res.end(
          JSON.stringify({ error: `Unexpected field(s) in request body: ${extra.join(', ')}` })
        );
      }
      if (typeof body.quantity !== 'number' || body.quantity < 0) {
        res.writeHead(400, { 'Content-Type': 'application/json' });
        return res.end(JSON.stringify({ error: 'quantity must be a number >= 0' }));
      }
      const lines = getLines(req);
      const idx = lines.findIndex((l) => l.productId === productId);
      if (body.quantity === 0) {
        if (idx !== -1) lines.splice(idx, 1);
      } else if (idx !== -1) {
        lines[idx].quantity = body.quantity;
      } else {
        lines.push({ productId, quantity: body.quantity });
      }
      const cart = enrich(lines, userId);
      res.writeHead(200, { 'Content-Type': 'application/json' });
      return res.end(JSON.stringify(cart));
    });
  }

  // @endpoint DELETE /api/cart/items/{productId}
  if (req.method === 'DELETE' && itemMatch) {
    const productId = decodeURIComponent(itemMatch[1]);
    const lines = getLines(req);
    const idx = lines.findIndex((l) => l.productId === productId);
    if (idx !== -1) lines.splice(idx, 1);
    const cart = enrich(lines, userId);
    res.writeHead(200, { 'Content-Type': 'application/json' });
    return res.end(JSON.stringify(cart));
  }

  // @endpoint POST /api/cart/checkout
  if (req.method === 'POST' && pathname === '/api/cart/checkout') {
    const lines = getLines(req);
    const cart = enrich(lines, userId);

    if (requestedStatusCode === '502') {
      res.writeHead(502, { 'Content-Type': 'application/json' });
      return res.end(JSON.stringify({ error: 'Could not create order' }));
    }
    if (requestedStatusCode === '400' || cart.items.length === 0) {
      res.writeHead(400, { 'Content-Type': 'application/json' });
      return res.end(JSON.stringify({ error: 'Cart is empty' }));
    }

    carts.set(sessionKey(req), []);
    const order = {
      id: 'mock-order-' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6),
      userId,
      items: cart.items.map(({ productId, name, price, quantity }) => ({
        productId,
        name,
        price,
        quantity,
      })),
      total: cart.total,
      status: 'confirmed',
      createdAt: new Date().toISOString(),
    };
    res.writeHead(201, { 'Content-Type': 'application/json' });
    return res.end(JSON.stringify(order));
  }

  res.writeHead(404, { 'Content-Type': 'application/json' });
  res.end(JSON.stringify({ error: 'Not found' }));
});

server.listen(PORT, () => {
  console.log(`Cart Service Mock listening on http://localhost:${PORT}`);
});
